# genex.toml, the world owner's: the template ships streaming off, and game.streaming then fails install streaming-disabled
[streaming]
enabled = true

// src/main.rs, the world's owner: 64 m cells round the player; rocks are things, pines a group.
// World holds player: Vec3, rocks: Vec<(CellId, Rock)> and ground: Option<(Terrain, [i32; 2])>.
use genex::prelude::*;
use genex::{CellBuild, CellId, InstanceGroup, Scatter, Streaming, Terrain, TerrainLayer, TerrainTiles};

/// The ground everywhere: pure (no world, no clock), so every thread and destination agrees.
fn height(x: f32, z: f32) -> f32 {
    8.0 * genex::math::sin(x / 97.0) * genex::math::cos(z / 131.0)
}

#[derive(Clone)]
pub struct Rock {
    at: Vec3,
}

fn wire_world(game: &mut Game<World>) {
    let tiles = TerrainTiles::procedural(65, height).expect("65 samples is a tile size");
    game.streaming(Streaming::grid(64.0).sim_radius(1).view_radius(448.0).terrain(tiles.clone()));
    let forest = Scatter::new(0.01, &[0]).with_scale(0.7, 1.4).following_ground(0.5);
    let cells = tiles.clone();
    game.cell_content(move |cell, inputs| {
        let (min, _) = inputs.bounds();
        let mut rng = inputs.rng(); // this cell's own generator
        let start = CellBuild::default();
        let Some(tile) = cells.tile(cell, 64.0) else { return start };
        let rocks = (0..3).fold(start, |build, _| {
            let (x, z) = (min.x + rng.unit() * 64.0, min.y + rng.unit() * 64.0);
            build.thing(Rock { at: vec3(x, tile.height(x, z), z) })
        });
        // Drawn while the cell is in view, uploaded once: no draw call for it anywhere.
        match InstanceGroup::models(&inputs.model("trees/pine.glb"), inputs.scatter(&tile, &forest)) {
            Ok(pines) => rocks.group(pines),
            Err(_) => rocks,
        }
    });
    game.cell_content(tiles.colliders_content(64.0)); // a heightfield collider per sim-active tile
    game.stream_colliders();
    game.on_reset(|sim, _, _, _| sim.stream.set_anchor("player", sim.world.player).expect("inside the world"));
    game.on_update(|sim, _| {
        for cell in sim.stream.entered() {
            let rocks: Vec<Rock> = cell.things::<Rock>().cloned().collect();
            sim.world.rocks.extend(rocks.into_iter().map(|rock| (cell.cell(), rock)));
        }
        let left = sim.stream.left().to_vec();
        sim.world.rocks.retain(|(cell, _)| !left.contains(cell));
        let at = sim.world.player;
        sim.stream.set_anchor("player", at).expect("inside the world");
        // The ground on screen: a 768 m patch round the player, rebuilt in another 256 m block.
        let block = [genex::math::round(at.x / 256.0) as i32, genex::math::round(at.z / 256.0) as i32];
        if sim.world.ground.as_ref().is_none_or(|(_, drawn)| *drawn != block) {
            let origin = vec2(block[0] as f32 * 256.0 - 384.0, block[1] as f32 * 256.0 - 384.0);
            let patch = Terrain::from_fn([385, 385], origin, 2.0, height).expect("heights");
            let patch = patch.with_layers(vec![TerrainLayer::flat(Color::rgb(86, 120, 58))]).expect("one layer");
            sim.world.ground = Some((patch, block));
        }
    });
    game.on_draw(|sim, frame, _| {
        if let Some((ground, _)) = &sim.world.ground {
            frame.tag("ground").terrain(ground);
        }
    });
    game.probe("streamed", |sim| json!({ "active": sim.stream.active().count(), "rocks": sim.world.rocks.len() }));
}
